Build the map step of the Git Hydrator. Reads git history via simple-git, chunks commits into groups of 50, calls claude-haiku-4-5-20251001 in parallel (concurrency: 5) on each chunk to extract architectural signal. Stores the raw summaries in memory — no disk writes yet (reduce step in H-003 does that).

Note: simple-git is already in backend/package.json from Phase 1 (E-001). No new dependency needed.

File: backend/src/lib/git-hydrator.ts
```typescript
import simpleGit from 'simple-git';
import { chatComplete } from './llm-client';

export interface GitChunkSummary {
  fromHash: string;
  toHash: string;
  commitCount: number;
  summary: string; // extracted signal from this chunk
}

export interface GitMapOptions {
  workspacePath: string;
  fromHash?: string;    // if set: only commits after this (delta sync)
  maxCommits?: number;  // default 1000
  chunkSize?: number;   // default 50
  concurrency?: number; // default 5
  mapModel?: string;    // default 'claude-haiku-4-5-20251001'
}

const MAP_PROMPT = `You are analyzing a chunk of git commit history. 
Extract ONLY information that would help an AI generate better code for this project:
- Major architectural decisions (e.g. "switched from Prisma to raw SQL")
- Recurring bug patterns that were fixed (e.g. "multiple fixes for timezone handling")
- Naming conventions established (e.g. "amount fields use cents not dollars")
- Deleted features or abandoned approaches
- Security or performance constraints added

Ignore: typos, formatting, dependency bumps, merge commits, minor refactors.
Respond with plain text bullet points only. Max 10 bullets. If nothing significant, respond: "No significant architectural changes in this chunk."`;

export async function gitMapStep(options: GitMapOptions): Promise<GitChunkSummary[]> {
  const {
    workspacePath,
    fromHash,
    maxCommits = 1000,
    chunkSize = 50,
    concurrency = 5,
    mapModel = 'claude-haiku-4-5-20251001',
  } = options;

  const git = simpleGit(workspacePath);

  // Verify it's a git repo
  const isRepo = await git.checkIsRepo();
  if (!isRepo) throw new Error(`Not a git repository: ${workspacePath}`);

  // Get commits: newest first (so we can limit easily)
  const logArgs: string[] = ['--oneline', `--max-count=${maxCommits}`];
  if (fromHash) logArgs.push(`${fromHash}..HEAD`);
  const logResult = await git.raw(['log', ...logArgs]);

  const commitLines = logResult.trim().split('\n').filter(Boolean);
  if (commitLines.length === 0) return []; // no new commits

  // Reverse so we process oldest-first (chronological)
  commitLines.reverse();

  // Chunk commits
  const chunks: string[][] = [];
  for (let i = 0; i < commitLines.length; i += chunkSize) {
    chunks.push(commitLines.slice(i, i + chunkSize));
  }

  // Get full diff for each chunk and run map LLM in parallel (concurrency-limited)
  const results: GitChunkSummary[] = [];

  for (let i = 0; i < chunks.length; i += concurrency) {
    const batch = chunks.slice(i, i + concurrency);
    const batchResults = await Promise.all(batch.map(async (chunk) => {
      const fromLine = chunk[0];
      const toLine = chunk[chunk.length - 1];
      const fromH = fromLine.split(' ')[0];
      const toH = toLine.split(' ')[0];

      // Get stat summary for this hash range (not full diff — avoids token explosion)
      const statOutput = await git.raw(['log', '--stat', '--no-merges', `${fromH}~1..${toH}`]).catch(() => chunk.join('\n'));

      // Truncate to 8000 chars to stay within cheap model token budget
      const truncated = statOutput.slice(0, 8000);

      const summary = await chatComplete(
        [{ role: 'user', content: `${MAP_PROMPT}\n\n---\nCOMMIT HISTORY:\n${truncated}` }],
        mapModel
      );

      return { fromHash: fromH, toHash: toH, commitCount: chunk.length, summary };
    }));
    results.push(...batchResults);
  }

  return results;
}

export function getLatestHash(summaries: GitChunkSummary[]): string | null {
  if (summaries.length === 0) return null;
  return summaries[summaries.length - 1].toHash;
}
```

